#![cfg(test)]
use nepl3_core::{budget::*,source::*,origin::*,diagnostic::*,diagnostic::validation::ReportValidationError,schema::*,value::*};
fn budget()->Budget{Budget::new(Limits{source_bytes:1_000_000,work:1_000_000,allocation_units:10_000_000,depth:1000,nodes:1_000_000,output_bytes:1_000_000,diagnostics:100,events:100})}
fn source(id:&str,rev:u64,text:&str,uri:&str)->SourceSnapshot{SourceSnapshot::new(SourceId(id.into()),rev,uri.into(),text.as_bytes().to_vec(),&mut budget()).expect("source")}
#[test] fn empty_lookup_must_preserve_cancelled_budget(){let mut b=budget();b.cancel();let got=SourceStore::default().get_revision_with_budget(&SourceId("missing".into()),0,&mut b).map(|v|v.is_some());assert_eq!(got,Err(StopReason::Cancelled));}
#[test] fn index_lookup_preserves_exact_revision_and_charged_name_comparisons(){let mut store=SourceStore::default();for name in ["z","a","???","aa"]{for rev in [7,0,3]{store.insert(source(name,rev,"x",&format!("memory:{name}:{rev}"))).expect("insert");}}for s in store.snapshots(){assert_eq!(store.get_revision_with_budget(&s.identity().source,s.identity().revision,&mut budget()).expect("find"),Some(s));}assert!(store.get_revision_with_budget(&SourceId("a".into()),1,&mut budget()).expect("absent").is_none());let mut l=budget().limits();l.work=0;assert_eq!(store.get_revision_with_budget(&SourceId("a".into()),7,&mut Budget::new(l)).map(|v|v.is_some()),Err(StopReason::WorkLimit));}
#[test] fn reports_preserve_duplicate_and_identity_uri_rules(){let store=SourceStore::default();let reg=SchemaRegistry::default();let report=Report::default();let a=source("a",0,"abc","memory:a");let z=source("z",0,"abc","memory:z");assert_eq!(report.validate(&store,&[z.clone(),a.clone(),a.clone()],&reg,&mut budget()),Ok(()));for changed in [source("a",0,"abc","memory:other"),source("a",0,"abd","memory:a")]{assert_eq!(report.validate(&store,&[z.clone(),a.clone(),changed.clone()],&reg,&mut budget()),Err(ReportValidationError::Source(SourceError::IdentityConflict)));let mut prior=SourceStore::default();prior.insert(a.clone()).expect("prior");assert_eq!(report.validate(&prior,&[changed],&reg,&mut budget()),Err(ReportValidationError::Source(SourceError::IdentityConflict)));}let mut l=budget().limits();l.allocation_units=0;assert_eq!(report.validate(&store,&[a],&reg,&mut Budget::new(l)),Err(ReportValidationError::Stopped(StopReason::AllocationLimit)));}
fn check(maps:&[Mapping],sources:&SourceStore,b:&mut Budget)->Result<(),OriginError>{SourceMap::validate_mappings(maps,sources,b).map(|_|())}
#[test] fn map_index_preserves_cycles_disjoint_self_edges_and_depth(){let a=source("a",0,"xxx","memory:a");let b=source("z",0,"xxx","memory:z");let c=source("a",1,"xxx","memory:a:1");let mut store=SourceStore::default();for s in [&b,&c,&a]{store.insert(s.clone()).expect("insert");}let edge=|s:&SourceSnapshot,x,y,t:&SourceSnapshot,u,v|Mapping{source:s.span(x,y).expect("span"),target:t.span(u,v).expect("span"),kind:MappingKind::Exact};let ab=edge(&a,0,1,&b,0,1);let bc=edge(&b,0,1,&c,0,1);let ca=edge(&c,0,1,&a,0,1);assert_eq!(check(&[bc.clone(),ab.clone(),ab.clone()],&store,&mut budget()),Ok(()));assert_eq!(check(&[ab.clone(),bc.clone(),ca],&store,&mut budget()),Err(OriginError::Cycle));assert_eq!(check(&[edge(&a,0,1,&a,1,2)],&store,&mut budget()),Ok(()));assert_eq!(check(&[edge(&a,0,1,&a,1,2),edge(&a,1,2,&a,0,1)],&store,&mut budget()),Err(OriginError::Cycle));let mut l=budget().limits();l.depth=2;assert_eq!(check(&[ab.clone(),bc.clone()],&store,&mut Budget::new(l)),Err(OriginError::Stopped(StopReason::DepthLimit)));for r in [Resource::Work,Resource::AllocationUnits]{let mut full=budget();check(&[ab.clone(),bc.clone()],&store,&mut full).expect("full");let max=match r{Resource::Work=>full.usage().work,_=>full.usage().allocation_units};for cap in 0..=max{let mut l=budget().limits();match r{Resource::Work=>l.work=cap,_=>l.allocation_units=cap};let got=check(&[ab.clone(),bc.clone()],&store,&mut Budget::new(l));assert!(matches!(got,Ok(())|Err(OriginError::Stopped(_))),"{got:?}");}println!("map {r:?} caps0..={max}");}}

#[test] fn report_added_index_resolves_exact_span_and_preserves_validation_stops(){
 let mut registry=SchemaRegistry::default();let descriptor=SchemaDescriptor{package:"review".into(),revision:1,types:vec![NamedType{name:"Args".into(),constraints:vec![],shape:TypeShape::Record{fields:vec![]}}],operations:vec![]};let schema=descriptor.reference(&mut budget()).expect("schema ref");registry.register(schema.clone(),descriptor,&mut budget()).expect("schema register");registry.finalize(&mut budget()).expect("schema finalize");
 let a=source("a",1,"xyz","memory:a");let z=source("z",0,"abc","memory:z");let mut report=Report::default();report.usage.events=1;report.events.push(Event{schema:schema.clone(),kind:"Hit".into(),operation_path:vec![],span:Some(a.span(1,2).expect("span")),payload:TypedValue::Record(Record{schema,kind:"Args".into(),fields:vec![]})});
 let added=vec![z,a.clone(),a.clone()];let store=SourceStore::default();assert_eq!(report.validate(&store,&added,&registry,&mut budget()),Ok(()));
 let unknown=source("a",2,"xyz","memory:a");let mut changed=report.clone();changed.events[0].span=Some(unknown.span(1,2).expect("span"));assert_eq!(changed.validate(&store,&added,&registry,&mut budget()),Err(ReportValidationError::Source(SourceError::MissingSnapshot)));
 let mut measured=budget();report.validate(&store,&added,&registry,&mut measured).expect("full");for resource in [Resource::Work,Resource::AllocationUnits]{let max=match resource{Resource::Work=>measured.usage().work,_=>measured.usage().allocation_units};for cap in 0..=max{let mut l=budget().limits();match resource{Resource::Work=>l.work=cap,_=>l.allocation_units=cap};let got=report.validate(&store,&added,&registry,&mut Budget::new(l));assert!(matches!(got,Ok(())|Err(ReportValidationError::Stopped(_))),"{got:?}");}println!("report {resource:?} caps0..={max}");}
}

#[test] fn all_three_vertex_mapping_graphs_match_independent_transitive_closure(){
 let a=source("z",0,"x","memory:z");let b=source("a",3,"x","memory:a3");let c=source("a",0,"x","memory:a0");let vertices=[a,b,c];let mut store=SourceStore::default();for s in &vertices{store.insert(s.clone()).expect("source");}
 for mask in 0u32..512{let mut reach=[[false;3];3];let mut maps=vec![];for i in 0..3{for j in 0..3{if mask&(1<<(i*3+j))!=0{reach[i][j]=true;maps.push(Mapping{source:vertices[i].span(0,1).expect("span"),target:vertices[j].span(0,1).expect("span"),kind:MappingKind::Exact});}}}for k in 0..3{for i in 0..3{for j in 0..3{reach[i][j]|=reach[i][k]&&reach[k][j];}}}let cycle=(0..3).any(|i|reach[i][i]);for _ in 0..2{let got=check(&maps,&store,&mut budget());assert_eq!(got,if cycle{Err(OriginError::Cycle)}else{Ok(())},"graph {mask}");maps.reverse();}}
 println!("512 graphs x 2 declaration orders agree with transitive closure");
}
